import 'basket/basket.dart';
import 'bowling/bowling.dart';
import 'common/mini_game_definition.dart';
import 'darts/darts.dart';
import 'freekick/freekick.dart';
import 'minigolf/minigolf.dart';
import 'penalty/penalty.dart';
import 'petanque/petanque.dart';
import 'stack/stack.dart';
import 'survival/survival.dart';

/// All mini-games, in catalog order (section 7). Generated by
/// `tools/register_games.py`: adding a game = create its folder + run it.
abstract final class GameRegistry {
  static const List<MiniGameDefinition> all = [
    MinigolfGame(),
    PenaltyGame(),
    FreekickGame(),
    BasketGame(),
    BowlingGame(),
    PetanqueGame(),
    DartsGame(),
    StackGame(),
    SurvivalGame(),
  ];

  static MiniGameDefinition? byId(String id) {
    for (final g in all) {
      if (g.id == id) return g;
    }
    return null;
  }
}
